head.script:
scwin.screenId = "jlddst50000";

///////// 1. 변수 및 선언 영역 /////////

scwin.timer = undefined;

scwin.svrTitle = undefined;


///////// 2. 초기화 영역 /////////

// 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님). 진입점 선두 단계.
/**
 * @method
 * @name scwin.init_nowVars
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_attrReals
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_attrReals = async function () {
    const attrRealsList = [{ childId: "a_44", attr: "src", fn: function () { return "http://" + String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("hostName"))) + "/"; } }];
    const root = (function () { try { const f = $c.win.getFrame(); return (f && f.render) ? f.render : null; } catch (e) { return null; } })();
    const hasText = function (t) { return /[가-힣A-Za-z0-9]/.test(String(t == null ? "" : t)); };
    let applied = 0;
    for (let i = 0; i < attrRealsList.length; i++) {
        const a = attrRealsList[i];
        const comp = $c.util.getComponent(a.childId);
        const el = (comp && comp.getID && root) ? root.querySelector("#" + comp.getID()) : null;
        if (!comp && !el) { console.warn("[sdd] 속성 실현 대상 부재: " + a.childId); continue; }
        let v;
        try { v = a.fn(); } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId + "." + a.attr }); continue; }
        if (a.attr === "style") {
            if (comp && typeof comp.setStyle === "function") {
                const decls = String(v).split(";");
                for (let di = 0; di < decls.length; di++) {
                    const kv = decls[di].split(":");
                    if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
                }
            } else if (el) { el.style.cssText = (el.style.cssText || "") + ";" + v; }
        } else if (a.attr === "label") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); } else if (el) { el.textContent = v; }
        } else if (a.attr === "__value") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); }
        } else if (a.attr === "__items") {
            if (comp && typeof comp.addItem === "function" && v && v.length) {
                let hasVal = false;
                for (let ii = 0; ii < v.length; ii++) { if (hasText(v[ii][0]) || hasText(v[ii][1])) { hasVal = true; break; } }
                if (hasVal) {
                    if (typeof comp.removeAll === "function") { comp.removeAll(); }
                    for (let ij = 0; ij < v.length; ij++) {
                        const lb = String(v[ij][1] || "");
                        comp.addItem(String(v[ij][0] || ""), hasText(lb) ? lb : "");
                    }
                }
            }
        } else if (a.attr === "class") {
            if (el) { el.className = v; }
        } else if (a.attr === "__html") {
            if (el && !el.querySelector('[class*="w2"], input, select, textarea, button')) { el.innerHTML = v; }
        } else if (el) {
            el.setAttribute(a.attr, v);
            if (a.attr === "src" && el.tagName === "IMG") { el.src = v; }
        }
        applied++;
    }
    return applied;
};

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "c_when_3", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "svrGubun" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("svrGubun")) === 'dev'); } }, { id: "c_when_5", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "svrGubun" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("svrGubun")) === 'test1'); } }, { id: "c_when_7", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "svrGubun" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("svrGubun")) === 'test2'); } }, { id: "c_when_9", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "svrGubun" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("svrGubun")) === 'real1'); } }, { id: "c_when_11", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "svrGubun" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("svrGubun")) === 'real2'); } }, { id: "c_when_13", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "svrGubun" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("svrGubun")) === 'dr1'); } }, { id: "c_when_15", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "svrGubun" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("svrGubun")) === 'dr2'); } }, { id: "c_otherwise_17", fn: function(){ return (!((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "svrGubun" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("svrGubun")) === 'dev') || (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "svrGubun" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("svrGubun")) === 'test1') || (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "svrGubun" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("svrGubun")) === 'test2') || (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "svrGubun" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("svrGubun")) === 'real1') || (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "svrGubun" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("svrGubun")) === 'real2') || (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "svrGubun" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("svrGubun")) === 'dr1') || (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "svrGubun" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("svrGubun")) === 'dr2'))); } }, { id: "c_when_98", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "index" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("index"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "index" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("index")))).length === 0)); } }, { id: "c_otherwise_105", fn: function(){ return (!((!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "index" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("index"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "index" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("index")))).length === 0)))); } }, { id: "if_svrGubun", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "svrGubun" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("svrGubun")) !== 'dr' && ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "isExaService" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("isExaService")) ==='Y'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
/**
 * @method
 * @name scwin.init_fillGen
 * @author Inswave
 * @date 2026. 09. 29
 * @param boxId
 * @returns
 * @hidden N
*/
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_99", entity: "dlt_index", countIds: [], cells: [{ childId: "__rc0", fn: function (v, i) { return String(v("idxIndEngNm")); } }, { childId: "__rc1", fn: function (v, i) { return String(v("clsprcIdx")); } }, { childId: "__rc2", fn: function (v, i) { return String(v("updownIdx")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getTotalRow();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_scrnmode", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("scrnmode")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init = function () {
    /* sdd-asis-lifecycle:begin init — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $('input').placeholder();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.init_disclosure
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_disclosure = function () {
    /* sdd-asis-lifecycle:begin init_disclosure — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("div.temp-contents").empty();
    if ("0" === "0") {
        $("div.temp-contents").load('/external/dst/main/main_contents.htm?_=' + new Date().getTime(), function() {
                scwin.init_disclosure_proc();
        });
    } else {
        if ("0" === "1") {
            $('div.temp-contents').load(scwin.getMainbatchUrl("today"), function() {
                    scwin.init_disclosure_proc();
            });
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.init_disclosure_proc
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_disclosure_proc = function () {
    /* sdd-asis-lifecycle:begin init_disclosure_proc — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    console.error("[sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
    $("section.main-important #main-today-all article").html($("div.temp-contents #main-today-all article").html());
    $("section.main-important #main-today-stockmkt article").html($("div.temp-contents #main-today-stockmkt article").html());
    $("section.main-important #main-today-kosdaqmkt article").html($("div.temp-contents #main-today-kosdaqmkt article").html());
    $("section.main-important #main-today-konexmkt article").html($("div.temp-contents #main-today-konexmkt article").html());
    $("section.main-important #main-today-drvclss article").html($("div.temp-contents #main-today-drvclss article").html());
    (console.error('[sdd] 이 화면 문서에 #currentDateTime 가 없다 — html() 무동작(as-is 는 공용 템플릿·소거된 요소를 잡았다)'), $("#currentDateTime")).html(scwin.getCurrentDateTime());
    scwin.mainImportant_init();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.init_schedule
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_schedule = function () {
    /* sdd-asis-lifecycle:begin init_schedule — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("section.schedule article.ir ul").empty();
    $("section.schedule article.ir ul").load('/main.do?method=searchIRSchedule');
    $("section.schedule article.stock ul").empty();
    $("section.schedule article.stock ul").load('/main.do?method=searchStockSchedule');
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $('section.news_spot article.stockindex ul').simple_slideshow5({ interval: 2500, btn: "section.news_spot article.stockindex h3.ttl a" });
        const detail_search_opt = { btn: "header.container section.search a.more", close: "a.btn-pop-close", handle: "hgroup.handle", e: "click" };
        $('section.detail_search.popup').dim_dialog(detail_search_opt);
        bt_util_init();
        scwin.gnb_init();
        if ("0" === "0") {
            $('section.main-important').load('/external/dst/main/main_contents.htm?_=' + new Date().getTime(), function(response, status, xhr) {
                    if (status === "error") {
                        scwin.loadJSP();
                    } else {
                        scwin.loadBatch();
                    }
                    if ($c.util.getComponent('ipt_scrnmode').getValue() === "3") {
                        $(".today.wrapper").removeClass("active");
                        $(".market.wrapper").removeClass("active");
                        $(".valueup.wrapper").addClass("active");
                        $(".ipo.wrapper").removeClass("active");
                        $(".bond.wrapper").removeClass("active");
                    } else {
                        $(".today.wrapper").addClass("active");
                        $(".market.wrapper").removeClass("active");
                        $(".valueup.wrapper").removeClass("active");
                        $(".ipo.wrapper").removeClass("active");
                        $(".bond.wrapper").removeClass("active");
                    }
            });
        } else {
            if ("0" === "1") {
                scwin.loadJSP();
            }
        }
        scwin.fnStart();
        scwin.fnBookmark();
        scwin.init_schedule();
        scwin.init();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst50000.onpageload' }); }
};

// [A] 초기 목록 미해결 — jlddst50000: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
