/**
 * @method
 * @name scwin.getMainbatchUrl
 * @author Inswave
 * @date 2026. 09. 29
 * @param type
 * @returns
 * @hidden N
*/
scwin.getMainbatchUrl = function (type) {
    /* sdd-asis-lifecycle:begin getMainbatchUrl — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (type === "today") {
        return "/batch.do?method=mainTodayDisclosureGenerator&scrnmode=1";
    } else {
        if (type === "market") {
            return "/batch.do?method=mainMarketListGenerator&scrnmode=1";
        } else {
            if (type === "ipo") {
                return "/batch.do?method=selectMainIPOSList&scrnmode=1";
            } else {
                if (type === "bond") {
                    return "/batch.do?method=selectMainBondsList&scrnmode=1";
                } else {
                    if (type === "valueup") {
                        return "/batch.do?method=mainValueupList&scrnmode=1";
                    }
                }
            }
        }
    }
    return "";
    /* sdd-asis-lifecycle:end */
};


