*/
scwin.bt_util_img_re = function () {
    /* sdd-asis-lifecycle:begin bt_util_img_re — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $('nav.bt_util ul.menu li').each(function() {
            const target = $(this).children("a");
            target.children("img").attr("src", target.children("img").attr("src").replace(target.data("rname"), target.data("oname")));
    });
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.gnb_init
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.gnb_init = function () {
    /* sdd-asis-lifecycle:begin gnb_init — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $('#gnb li').each(function() {
            $(this).children("a.nm").bind("mouseover focus", function() {
                    $(this).children("span").children("img").fadeOut(600);
            });
            $(this).children("a.nm").bind("mouseleave focusout", function() {
                    $(this).children("span").children("img").fadeIn(600);
            });
    });
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnTopNoticeOpen
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnTopNoticeOpen = async function () {
    /* sdd-asis-lifecycle:begin fnTopNoticeOpen — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (nCnt == 0) {
        await $c.win.alert("표시할 공지사항이 없습니다.");
        return;
    }
    $('section#topnotice article.ctt li:first').addClass("first");
    const style = $('#topnotice').attr("style");
    let bgpy = $('#topnotice').height() + "px";
    if (style.search("block") > 0) {
        bgpy = "0px";
    }
    setTimeout(function() {
            $('#topnotice').slideToggle(200);
            $("body").animate({ 'background-position-y': bgpy }, 200);
            if (nCnt > 1) {
                const slider_notice = $('.bxslider-notice').bxSlider({ mode: "fade", auto: true, speed: 200, autoControls: true });
            }
        }, 200);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.activeImgName
 * @author Inswave
 * @date 2026. 09. 29
 * @param src
 * @returns
 * @hidden N
*/
scwin.activeImgName = function (src) {
    /* sdd-asis-lifecycle:begin activeImgName — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const data = {  };
    const hover_str = "_active";
    const tmp = src.split("/");
    const ext = /^.+\.([^.]+)$/.exec(tmp[3]);
    data.filename = tmp[3].replace("." + ext[1], "");
    data.rov_filename = data.filename + hover_str + "." + ext[1];
    data.filename = data.filename + "." + ext[1];
    return data;
    /* sdd-asis-lifecycle:end */
};
